content:
@layer components {
  .card {
    display: flex;
    flex-direction: column;
    border-radius: var(--shelf-radius-md);
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-inline-end: 0;
  }
  .drawer-overlay {
    background-color: var(--shelf-bgColor-overlay);
  }
}

@layer tokens {
  :root {
    --shelf-bgColor-default: hsl(30 15% 97%);
    --shelf-card-bgColor: var(--shelf-bgColor-raised);
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body { margin: 0; }
}

@layer components {
  .card {
    display: flex;
    flex-direction: column;
    border-radius: var(--shelf-radius-md);
  }
}

@custom-media --viewport-md (width >= 768px);

@layer tokens {
  :root { --shelf-bgColor-default: hsl(30 15% 97%); }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body { margin: 0; }
}

@layer tokens {
  :root {
    --shelf-card-bgColor: var(--shelf-bgColor-raised);
    --shelf-chip-fgColor-rest: var(--shelf-fgColor-default);
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body { margin: 0; }
}

@layer tokens {
  :root { --shelf-bgColor-default: hsl(30 15% 97%); }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body { margin: 0; background-color: var(--shelf-bgColor-default); }
  ul { margin: 0; padding: 0; list-style: none; }
  p { margin: 0; }
}

@layer components {
  .fab {
    position: fixed;
    inset-block-end: var(--shelf-space-lg);
    inset-inline-end: var(--shelf-space-lg);
  }
}
